ALTER TABLE public.workshop_status_records ADD CONSTRAINT workshop_status_records_other_disposition CHECK (((final_disposition IS DISTINCT FROM 'other'::text) OR (NULLIF(btrim(final_disposition_remarks), ''::text) IS NOT NULL)));
